impl BlockSimulator {
    fn new(accel_3n: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            // L X M > T R
            left_tape: vec![L, Run(I, 5)],
            right_tape: vec![R0],
            state: HigherState::RightA,
            base_steps: 9,
            self_steps: 0,
            accel_3n,
        }
    }

    fn new_standard(exp: Exp, accel_3n: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, Run(I, exp)],
            right_tape: vec![R],
            state: HigherState::RightA,
            base_steps: 0,
            self_steps: 0,
            accel_3n,
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;
        if self.accel_3n
            && let Some(Run(I, exp)) = self.left_tape.last()
            && *exp >= 3
            && self.state == RightA
            && matches!(self.right_tape.as_slice(), [R])
        {
            let n = *exp / 3;
            let rem = *exp % 3;
            self.left_tape.pop();
            if rem > 0 {
                self.left_tape.push(Run(I, rem));
            }
            self.state = Left;
            self.right_tape.push(Run(X, n * 4 + 3));

            // self.base_steps += n * n * 12 + 41 * n + 33;
            self.self_steps += 1;
            return Ok(());
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self
            .base_steps
            .checked_add(new_base_steps.into())
            .ok_or(SimError::Overflow)?;
        self.self_steps += 1;
        Ok(())
    }
}

